/**
 * Minimal R2 binding types, hand-written rather than generated by
 * `wrangler types` — the full workerd runtime type dump redeclares the
 * global `Response`/`Body` interfaces with a generic `json<T>()`, which
 * breaks type inference for every `fetch(...).json()` call in client
 * components project-wide. This declares only what the admin storage code
 * actually uses.
 */

interface R2HTTPMetadata {
  contentType?: string;
  contentLanguage?: string;
  contentDisposition?: string;
  contentEncoding?: string;
  cacheControl?: string;
  cacheExpiry?: Date;
}

interface R2Object {
  key: string;
  size: number;
  httpMetadata?: R2HTTPMetadata;
}

interface R2ObjectBody extends R2Object {
  body: ReadableStream;
  bodyUsed: boolean;
  arrayBuffer(): Promise<ArrayBuffer>;
  text(): Promise<string>;
  json<T = unknown>(): Promise<T>;
  blob(): Promise<Blob>;
}

interface R2Objects {
  objects: R2Object[];
  truncated: boolean;
  cursor?: string;
}

interface R2ListOptions {
  prefix?: string;
  cursor?: string;
  limit?: number;
}

interface R2PutOptions {
  httpMetadata?: R2HTTPMetadata;
}

interface R2Bucket {
  get(key: string): Promise<R2ObjectBody | null>;
  put(
    key: string,
    value: ReadableStream | ArrayBuffer | ArrayBufferView | string | Blob | null,
    options?: R2PutOptions
  ): Promise<R2Object>;
  list(options?: R2ListOptions): Promise<R2Objects>;
  delete(key: string): Promise<void>;
}

interface Fetcher {
  fetch: typeof fetch;
}
